def preserve_accounting(apps, schema_editor):
    Budget = apps.get_model("service", "Budget")
    Operation = apps.get_model("service", "Operation")
    User = apps.get_model("service", "User")
    Treasury = apps.get_model("service", "Treasury")
    FundingEntry = apps.get_model("service", "FundingEntry")
    totals = Budget.objects.exclude(month=date(1970, 1, 1)).aggregate(
        spent=models.Sum("spent"), reserved=models.Sum("reserved")
    )
    Treasury.objects.create(
        pk=1,
        processing_spent=totals["spent"] or Decimal(0),
        processing_reserved=totals["reserved"] or Decimal(0),
    )
    if totals["spent"] and totals["spent"] > 0:
        FundingEntry.objects.create(
            kind="historical_processing_cost",
            amount_usd=totals["spent"],
            source="historical",
            reference="opening-processing",
            occurred_at=None,
        )
    Operation.objects.filter(state="running").update(
        authorized_cost=models.F("reserved_cost")
    )
    for user in User.objects.all().iterator():
        last = Operation.objects.filter(user=user).aggregate(
            last=models.Max("created_at")
        )["last"]
        dates = [value for value in (last, user.last_login) if value]
        if dates:
            user.hosted_requested_at = min(dates)
            user.hosted_last_active_at = max(dates)
            user.save(update_fields=["hosted_requested_at", "hosted_last_active_at"])


